import java.util.List;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute naming the steward a user delegated the steward role acts for: each line of a
     *  change they make ends with for=<steward>, but for the lines that only report figures. */
    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";

    /** The events that only report figures, and so carry no for=. */
    private static final String[] FIGURES = { "ROLLUP ", "TOTALS ", "ALERT " };

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back (by any rule) writes nothing. Outside a transaction the record is written now.
     */
    public void recordOnCommit(String line) {
        String entry = line + actingFor(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    private static String actingFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
        if (steward == null) {
            return "";
        }
        for (String figures : FIGURES) {
            if (entry.startsWith(figures)) {
                return "";
            }
        }
        return " for=" + steward;
    }

    /** Every record the file holds now, in the order written (none when there is no file yet). */
    public synchronized List<String> lines() {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's audit lines, as the audit file holds them. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/audit")
public class AuditController {

    private final AuditViewService service;

    public AuditController(AuditViewService service) {
        this.service = service;
    }

    /** The sheet's audit lines, newest first; with a name, only those about that person. */
    @GetMapping
    public List<String> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestParam(defaultValue = "") @Size(max = 200) String name) {
        return service.lines(sheetId.trim(), name);
    }
}
package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.TreeSet;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Reads a sheet's records back out of the audit file, newest first. It reads what the file holds;
 * it keeps no record of its own.
 */
@Service
public class AuditViewService {

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditViewService(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    /**
     * The sheet's audit lines, newest first. With a name, only the lines about that person: those
     * carrying name=&lt;name&gt; or person=&lt;name&gt;, the name compared as names are (case and
     * surrounding spaces ignored); the lines about them on the sheet's descendants follow, each sheet's
     * newest first, the sheets by id; when the person of that name on the sheet was transferred here, the
     * lines about them on the sheet they came from follow, newest first, as that sheet's file holds them.
     */
    public List<String> lines(String sheetId, String name) {
        List<String> lines = sheetLines(sheetId, name);
        String who = name == null ? "" : name.trim();
        if (!who.isEmpty()) {
            for (String descendant : descendants(sheetId)) {
                lines.addAll(sheetLines(descendant, who));
            }
            String origin = people.findByNameOrAlias(sheetId, who).map(Person::getOriginSheet).orElse(null);
            if (origin != null && !origin.equals(sheetId)) {
                lines.addAll(sheetLines(origin, who));
            }
        }
        return lines;
    }

    /** The sheet's children, theirs and so on, by id. */
    private TreeSet<String> descendants(String sheetId) {
        TreeSet<String> found = new TreeSet<>();
        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            for (Sheet child : sheets.findByParentOrderByIdAsc(next.pop())) {
                if (!child.getId().equals(sheetId) && found.add(child.getId())) {
                    next.add(child.getId());
                }
            }
        }
        return found;
    }

    private List<String> sheetLines(String sheetId, String name) {
        Pattern sheet = Pattern.compile("(?:^| )sheet=" + Pattern.quote(sheetId) + "(?: |$)");
        String who = name == null ? "" : name.trim();
        Pattern person = who.isEmpty() ? null
                : Pattern.compile("(?:^| )(?:name|person)=" + Pattern.quote(who) + "(?= [A-Za-z][\\w-]*=|$)",
                        Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
        List<String> lines = new ArrayList<>();
        for (String line : audit.lines()) {
            if (sheet.matcher(line).find() && (person == null || person.matcher(line).find())) {
                lines.add(line);
            }
        }
        Collections.reverse(lines);
        return lines;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

// The active sheet's audit lines, read back from the audit file as it holds them now.
@Injectable({ providedIn: 'root' })
export class AuditLog {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's audit lines, newest first; with a name, only those about that person. An error message when that failed. */
  async lines(name: string): Promise<{ lines: string[] } | { error: string }> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return { error: 'Load a sheet first.' };
    try {
      const lines = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sid)}/audit`, {
          headers: { 'X-User': user },
          params: { name: name.trim() },
        }),
      );
      return { lines };
    } catch (e) {
      return { error: e instanceof HttpErrorResponse ? `Could not read the audit (${e.status}).` : 'Could not read the audit.' };
    }
  }
}
import { Component, computed, inject, signal } from '@angular/core';
import { AuditLog } from '../../core/audit';
import { Session } from '../../core/session';

// The audit viewer: with the filter blank it lists every audit line of the sheet, newest first, exactly as
// the file holds it; with a name, only the lines about that person (name= or person=). It reads the file;
// it records nothing.
@Component({
  selector: 'app-audit',
  template: `
    <section aria-label="Audit" data-testid="audit">
      <h2>Audit</h2>
      <form (submit)="show($event)">
        <label for="audit-filter">Person (blank for all)</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>
      <ol data-testid="audit-list" aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditPanel {
  private readonly audit = inject(AuditLog);
  private readonly session = inject(Session);
  protected readonly filter = signal('');
  protected readonly error = signal<string | null>(null);
  private readonly shown = signal<{ sheet: string | null; lines: string[] }>({ sheet: null, lines: [] });
  /** The lines last shown, while they are of the sheet loaded now. */
  protected readonly lines = computed(() => {
    const s = this.shown();
    return s.sheet === this.session.sheetId() ? s.lines : [];
  });
  private shows = 0;

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    const show = ++this.shows;
    const sheet = this.session.sheetId();
    this.error.set(null);
    this.shown.set({ sheet: null, lines: [] });
    const res = await this.audit.lines(this.filter());
    if (show !== this.shows) return; // a later press has taken over
    if ('error' in res) this.error.set(res.error);
    else this.shown.set({ sheet, lines: res.lines });
  }
}

